arguments.command:
cd /home/user/RL_Study/report-gepa/runs/originals/hype && cat > facts.json <<'JSON'
[
  {
    "id": "top100-superstars",
    "source": "Just 31 players eventually reached “superstar” status (based on advanced statistics, details at the bottom).",
    "claim": "31 of the 1,535 top-100 recruits (2.0%) had a mean composite rank of 30 or better, the story's superstar level.",
    "tables": {"p": "data/players.csv"},
    "code": "p[p['rank'].notna()].assign(comp=lambda x: x[['top_mean_vorp_rank','top_mean_wa_rank']].mean(axis=1))['comp'].le(30).agg(['sum','size','mean'])"
  },
  {
    "id": "top100-past-two-seasons",
    "source": "only 25% made it past their two-year rookie contract",
    "claim": "378 of the 1,535 top-100 recruits (24.6%) played more than two NBA seasons.",
    "tables": {"p": "data/players.csv"},
    "code": "p[p['rank'].notna()]['total_seasons'].gt(2).agg(['sum','size','mean'])"
  },
  {
    "id": "top10-nba-share",
    "source": "a full 84% of them eventually made it to the NBA",
    "claim": "132 of the 158 top-10 recruits (83.5%) played at least one NBA season.",
    "tables": {"p": "data/players.csv"},
    "code": "p[p['rank']<=10]['total_seasons'].ge(1).agg(['sum','size','mean'])"
  },
  {
    "id": "straight-to-nba-players",
    "source": "Percentage of players that reach each level (out of 35 players) from 1998 - 2005",
    "claim": "35 players who never attended college were drafted between 1998 and 2005.",
    "tables": {"p": "data/players.csv"},
    "code": "p[(p['college'].isna()) & (p['draft_year'].between(1998,2005))].shape[0]"
  },
  {
    "id": "straight-to-nba-past-rookie",
    "source": "94% made it past their rookie contract",
    "claim": "32 of the other 34 straight-to-NBA players (94.1%) played at least one NBA season.",
    "tables": {"p": "data/players.csv"},
    "code": "p[(p['college'].isna()) & (p['draft_year'].between(1998,2005)) & (p['name']!='Korleone Young')]['total_seasons'].ge(1).agg(['sum','size','mean'])"
  },
  {
    "id": "straight-to-nba-mediocre",
    "source": "55% eventually becoming mediocre or better NBA players",
    "claim": "19 of the other 34 straight-to-NBA players (55.9%) reached mediocre or better, a composite rank of 120 or better.",
    "tables": {"p": "data/players.csv"},
    "code": "p[(p['college'].isna()) & (p['draft_year'].between(1998,2005))].assign(comp=lambda x: x[['top_mean_vorp_rank','top_mean_wa_rank']].mean(axis=1)).query(\"name != 'Korleone Young'\")['comp'].le(120).agg(['sum','size','mean'])"
  },
  {
    "id": "unranked-nba-players",
    "source": "We found 338 of these players that were eventually drafted into the NBA, despite being undervalued in high school.",
    "claim": "338 players outside the top 100 appeared in the NBA.",
    "tables": {"p": "data/players.csv"},
    "code": "(p['rank'].isna() & p['bbrID'].notna()).sum()"
  },
  {
    "id": "drafted-ranked-past-rookie",
    "source": "92% of the drafted and ranked players made it past their rookie contract",
    "claim": "401 of the 432 drafted top-100 recruits (92.8%) played at least one NBA season.",
    "tables": {"p": "data/players.csv"},
    "code": "p[p['rank'].notna() & p['pick_overall'].notna()]['total_seasons'].ge(1).agg(['sum','size','mean'])"
  },
  {
    "id": "unranked-two-seasons",
    "source": "only 73% of the unranked and drafted players stayed more than two years",
    "claim": "248 of the 338 unranked players (73.4%) played at least two NBA seasons.",
    "tables": {"p": "data/players.csv"},
    "code": "p[p['rank'].isna()]['total_seasons'].ge(2).agg(['sum','size','mean'])"
  },
  {
    "id": "unranked-superstars",
    "source": "Seven players—Dwyane Wade, Marc Gasol, Paul George, Jimmy Butler,Russell Westbrook, Stephen Curry, and Damian Lillard—whose high school careers were apparently not worthy of a spot amongst the top 100, still broke into the ranks of superstars in their NBA careers.",
    "claim": "Seven unranked players—Damian Lillard, Dwyane Wade, Jimmy Butler, Marc Gasol, Paul George, Russell Westbrook and Stephen Curry—reached a composite rank of 30 or better.",
    "tables": {"p": "data/players.csv"},
    "code": "p[p['rank'].isna()].assign(comp=lambda x: x[['top_mean_vorp_rank','top_mean_wa_rank']].mean(axis=1)).query('comp <= 30').sort_values('name')[['name','comp']].to_string(index=False)"
  }
]
JSON
cat > skipped.json <<'JSON'
[
  {
    "source": "27% of the 1,563 top-ranked high school players made it to the NBA",
    "why": "The file has 1,535 ranked players, not 1,563, and no simple story-consistent filter reproduces 27%: at least one NBA season is 521/1,535 (33.9%), two or more seasons is 437/1,535 (28.5%), and drafted plus at least one season is 401/1,535 (26.1%)."
  },
  {
    "source": "441 of the 900 draft picks in that 15 year span were top 100 recruits.",
    "why": "The file contains only the cohort of top-100 and unranked high-school players, not all 900 draft picks in 1998-2013; it has 575 draft picks in those years and only 403 top-100 picks drafted in 1998-2013 (432 overall), so neither 441 nor 900 is reproduced."
  },
  {
    "source": "Percentage of players that reach each level (out of 157 players) from 1998 - 2013",
    "why": "The four named colleges total 147 top-100 recruits in the file (154 including all unranked players with those colleges), not 157, so the Big 4 chart's denominator and level percentages are not reproduced."
  },
  {
    "source": "Young, the #3 ranked high school player in 1998, ultimately fizzled out of the NBA having played only 15 minutes across 3 games.",
    "why": "The file has no minutes or games-played fields; it only records total_seasons = 1 and valid_seasons = 0 for Korleone Young."
  },
  {
    "source": "Despite being the #1 high school recruit in 2000—something that you think would indicate future NBA stardom—he put together a meager career in the league, averaging around 5 points per game over 5 years.",
    "why": "The file has no points-per-game data, so Harvey's scoring average cannot be checked; only his five NBA seasons are present."
  },
  {
    "source": "Below we widen the field to take a look at the biggest NBA-producing colleges and see how many yield NBA talent.",
    "why": "The college chart's per-college counts for drafted players and players with fewer than three seasons do not match the file (for example, Kentucky shows 23 drafted in the chart but has 22 pick_overall records), so the chart's six columns cannot be reproduced as a whole. The total players per college and the composite-rank thresholds do match, but the chart's level labels do not map unambiguously to the file's columns."
  }
]
JSON
python3 -m json.tool facts.json > /dev/null && python3 -m json.tool skipped.json > /dev/null && echo OK

